import React from "react";

import '../App.css';
import 'bootstrap/dist/css/bootstrap.css';
import { Container,Row,Col } from 'react-bootstrap';



function Accueil(){
    return(
      <Container>
        <Row>
          <Col>
          <div className="bordure">1</div>
          </Col>
          <Col>
          <div className="bordure">2</div>
          </Col>
          <Col>
          <div className="bordure">3</div>
          </Col>
        </Row>
      </Container>
    )
}

export default Accueil
